224	export function computeCampaignMetrics(
225	  candidates: Candidate[],
226	  prev?: Partial<CampaignMetrics>,
227	  /** Real elapsed hours from campaign creation to the first booked interview
228	   *  (caller computes this from actual timestamps — see recomputeMetrics in
229	   *  store.ts). `undefined` preserves whatever was already on `prev`; pass
230	   *  `null` explicitly once no booking exists yet. */
231	  timeToFirstInterviewHours?: number | null,
232	  realFacts?: Pick<RealFunnelFacts, "contacted" | "repliedCount" | "booked" | "replyRate">,
233	): CampaignMetrics {
234	  const sourced = candidates.length;
235	  const stageContacted = candidates.filter((c) => effectiveStageRank(c) >= 1).length;
236	  const stageReplied = candidates.filter((c) => effectiveStageRank(c) >= 2).length;
237	  const interested = candidates.filter(
238	    (c) => effectiveStageRank(c) >= 3 && c.stage !== "Not Interested",
239	  ).length;
240	  const stageBooked = candidates.filter((c) => effectiveStageRank(c) >= 4).length;
241	  const interviewed = candidates.filter((c) =>
242	    ["Interviewed", "Offer", "Hired"].includes(c.stage),
243	  ).length;
244	  const offer = candidates.filter((c) => ["Offer", "Hired"].includes(c.stage)).length;
245	  const hired = candidates.filter((c) => c.stage === "Hired").length;
246	  const notInterested = candidates.filter((c) => c.stage === "Not Interested").length;
247	  const scores = candidates.map((c) => c.matchScore).filter(Boolean);
248	  const avg = scores.length ? round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
249	  const contacted = realFacts?.contacted ?? stageContacted;
250	  const replied = realFacts?.repliedCount ?? stageReplied;
251	  const booked = realFacts?.booked ?? stageBooked;
252	
253	  return {
254	    sourced,
255	    contacted,
256	    replied,
257	    interested,
258	    booked,
259	    interviewed,
260	    offer,
261	    hired,
262	    notInterested,
263	    replyRate: realFacts?.replyRate ?? (contacted ? replied / contacted : 0),
264	    avgMatchScore: avg,
265	    timeToFirstInterviewHours:
266	      timeToFirstInterviewHours !== undefined
267	        ? timeToFirstInterviewHours
268	        : (prev?.timeToFirstInterviewHours ?? null),
269	    emailsSentToday: prev?.emailsSentToday ?? 0,
270	    linkedinSentToday: prev?.linkedinSentToday ?? 0,
271	  };
272	}
