157	/**
158	 * Base query text for a web-search-sourced platform, built from the campaign's
159	 * existing sourcing strategy (no new query-building system — reuses the boolean/
160	 * tag strings already generated by buildSourcingStrategy). The route scopes this
161	 * with `site:` per platform.
162	 */
163	function baseWebQuery(campaign: Campaign, platform: WebSearchPlatform): string {
164	  const jd = campaign.jobAnalysis;
165	  if (platform === "LinkedIn") return campaign.sourcingStrategy.linkedinBoolean;
166	  if (platform === "Stack Overflow") {
167	    const tags = campaign.sourcingStrategy.stackOverflowTags;
168	    return tags.length ? tags.map((t) => `"${t}"`).join(" OR ") : jd.title;
169	  }
170	  // Dribbble / Behance are portfolio platforms — a boolean recruiter string
171	  // doesn't fit; title + top skill is what a human would actually search.
172	  return [jd.title, jd.requiredSkills[0] ?? ""].filter(Boolean).join(" ");
173	}
