175	/**
176	 * Parse the "Source via Sillage" dialog's single free-text field into the
177	 * identifier shape /api/source/sillage/start expects — a linkedin.com URL is
178	 * sent as linkedinUrl, anything else as a bare domain (protocol/www/path
179	 * stripped if the operator pasted a full URL).
180	 */
181	function parseSillageIdentifier(input: string): { domain?: string; linkedinUrl?: string } {
182	  const trimmed = input.trim();
183	  if (/linkedin\.com\//i.test(trimmed)) {
184	    return { linkedinUrl: /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}` };
185	  }
186	  return { domain: trimmed.replace(/^https?:\/\//i, "").replace(/^www\./i, "").split("/")[0] };
187	}
