189	/**
190	 * Map real Sillage account-mapping profiles into scored, deduped Candidates —
191	 * the live counterpart to mapGithubCandidates/mapWebSearchCandidates (mock-ai.ts),
192	 * same scoring + dedupe pipeline, real data. Kept here rather than mock-ai.ts
193	 * because it needs the campaign's live effective weights, which only exist in
194	 * this client-side store — /api/source/sillage/status has no access to campaign
195	 * state and returns raw profiles only.
196	 */
197	function mapSillageCandidates(
198	  profiles: SillageProfile[],
199	  campaign: Campaign,
200	  companyLabel: string,
201	  existing: Candidate[],
202	  weights: ScoringWeights = campaign.scoringWeights,
203	): SourceResult {
204	  const jd = campaign.jobAnalysis;
205	  const allSkills = [...jd.requiredSkills, ...jd.niceToHaveSkills];
206	  const raw: Candidate[] = profiles.map((p) => {
207	    const name = [p.firstName, p.lastName].filter(Boolean).join(" ").trim() || "Unknown";
208	    const headline = (p.headline ?? "").trim();
209	    const about = (p.about ?? "").trim();
210	    const hay = `${p.position ?? ""} ${headline} ${about}`.toLowerCase();
211	    const techStack = allSkills.filter((s) => hay.includes(s.toLowerCase()));
212	    const location = [p.location?.city, p.location?.region, p.location?.country].filter(Boolean).join(", ");
213	    return {
214	      id: genId("cand"),
215	      campaignId: campaign.id,
216	      name,
217	      email: p.email ?? "",
218	      phone: p.phone ?? undefined,
219	      avatarInitials: initialsFrom(name),
220	      currentTitle: p.position || jd.title,
221	      currentCompany: companyLabel,
222	      location,
223	      timezone: "",
224	      linkedinUrl: p.linkedinUrl ?? "",
225	      githubUrl: "",
226	      sourcePlatform: "Sillage",
227	      sourceQuery: companyLabel,
228	      matchScore: 0,
229	      matchBreakdown: [],
230	      techStack,
231	      yearsExperience: jd.minYearsExperience ?? (jd.seniority === "Senior" ? 6 : 4),
232	      companyStageExperience: [],
233	      industryExperience: [],
234	      recentActivity: headline || about.slice(0, 140) || `Sourced via Sillage account mapping: ${companyLabel}.`,
235	      stage: "Sourced",
236	      lastContactedAt: null,
237	      outreachHistory: [],
238	      replyHistory: [],
239	      booking: null,
240	      complianceFlags: {
241	        doNotContact: false,
242	        suppressed: false,
243	        unsubscribed: false,
244	        gdprExportRequested: false,
245	        anonymized: false,
246	        suppressedUntil: null,
247	      },
248	      createdAt: new Date().toISOString(),
249	      provenance: "live",
250	    };
251	  });
