 50	function usePrefersReducedMotion(): boolean {
 51	  const [reduced, setReduced] = React.useState(false);
 52	  React.useEffect(() => {
 53	    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
 54	    setReduced(mq.matches);
 55	    const onChange = () => setReduced(mq.matches);
 56	    mq.addEventListener("change", onChange);
 57	    return () => mq.removeEventListener("change", onChange);
 58	  }, []);
 59	  return reduced;
