 62	function bucketEvents(events: AgentEvent[], now: number): number[] {
 63	  const buckets = new Array(SPARK_BUCKET_COUNT).fill(0) as number[];
 64	  const windowMs = SPARK_BUCKET_COUNT * SPARK_BUCKET_MS;
 65	  for (const e of events) {
 66	    const age = now - e.at;
 67	    if (age < 0 || age >= windowMs) continue;
 68	    const idx = SPARK_BUCKET_COUNT - 1 - Math.floor(age / SPARK_BUCKET_MS);
 69	    if (idx >= 0 && idx < SPARK_BUCKET_COUNT) buckets[idx] += 1;
 70	  }
 71	  return buckets;
 72	}
