 94	  const checkDeltas = React.useCallback(() => {
 95	    const latest = valuesRef.current;
 96	    const prev = lastSeenRef.current;
 97	    const until = Date.now() + FLASH_MS;
 98	    let changed: Partial<Record<TileKey, Flash>> | null = null;
 99	    for (const key of TILE_ORDER) {
