 26	/* ============================================================================
 27	   3.3 Autopilot Replay (DVR) — scrub the agents' whole day. Purely a read/
 28	   derived view: buildEventStream + replayStateAt (src/lib/replay.ts) turn
 29	   existing candidate/outreach/reply/booking/report history into a time-
 30	   ordered stream, precomputed once per store-state and binary-searched on
 31	   every cursor change — no store writes happen anywhere on this page.
 32	   ========================================================================== */
 33	
 34	const Floor3D = dynamic(() => import("@/components/floor3d/Floor3D"), { ssr: false });
 35	
 36	const KIND_LABEL: Record<ReplayEventKind, string> = {
 37	  source: "Sourced",
 38	  score: "Scored",
 39	  draft: "Drafted",
 40	  approve: "Approved",
 41	  reply: "Replied",
 42	  book: "Booked",
 43	  report: "Reported",
 44	};
 45	
 46	export default function ReplayPage() {
 47	  const hydrated = useHydrated();
 48	  const candidates = useCandidates();
 49	  const outreach = useOutreach();
 50	  const replies = useReplies();
 51	  const bookings = useBookings();
 52	  const reports = useReports();
 53	  const activities = useActivities();
 54	  const seats = useSeats();
 55	  const ledger = useLedger();
 56	  const settings = useSettings();
 57	
 58	  const [selectedAgentId, setSelectedAgentId] = React.useState<string | null>(null);
 59	  // null = "follow the end of the stream" (fully revealed) until the operator
 60	  // drags the playhead for the first time, at which point it's pinned.
 61	  const [cursorMs, setCursorMs] = React.useState<number | null>(null);
 62	
 63	  // Narrow "stateLike" object — same convention /floor uses (src/app/floor/
 64	  // page.tsx) to assemble exactly the slice of state a helper needs from
 65	  // selector hooks. Memoized so its identity only changes when one of the
 66	  // underlying arrays actually changes (store selectors return stable
 67	  // references between renders that don't touch that slice), which is what
 68	  // lets replay.ts's internal WeakMap cache turn every cursor-only re-render
 69	  // into an O(1) cache hit instead of rebuilding the whole event stream.
 70	  const stateLike = React.useMemo(
 71	    () => ({ candidates, outreach, replies, bookings, reports, activities, seats, ledger }),
 72	    [candidates, outreach, replies, bookings, reports, activities, seats, ledger],
 73	  );
 74	
 75	  const stream = React.useMemo(() => buildEventStream(stateLike), [stateLike]);
 76	  const minMs = stream[0]?.at ?? Date.now();
 77	  const maxMs = stream.length > 0 ? stream[stream.length - 1].at : minMs;
 78	  const effectiveCursor = cursorMs ?? maxMs;
 79	
 80	  const derived = React.useMemo(
 81	    () => replayStateAt(stateLike, effectiveCursor),
 82	    [stateLike, effectiveCursor],
 83	  );
 84	
 85	  const lastEventByCandidate = React.useMemo(() => {
 86	    const map = new Map<string, ReplayEvent>();
 87	    // Events are chronological, so the last write for a given candidateId
 88	    // is always its most recent revealed event.
 89	    for (const e of derived.events) {
 90	      if (e.candidateId) map.set(e.candidateId, e);
 91	    }
 92	    return map;
 93	  }, [derived.events]);
 94	
 95	  const revealedCandidates = React.useMemo(
 96	    () =>
 97	      candidates
 98	        .filter((c) => derived.revealedCandidateIds.has(c.id))
 99	        .sort((a, b) => (lastEventByCandidate.get(b.id)?.at ?? 0) - (lastEventByCandidate.get(a.id)?.at ?? 0)),
100	    [candidates, derived.revealedCandidateIds, lastEventByCandidate],
101	  );
102	
103	  return (
104	    <div className="animate-fade-in">
105	      <PageHeader
106	        eyebrow="Ops Floor"
107	        title="Autopilot Replay"
108	        description="Drag the playhead to scrub the agents' whole day. Candidates reveal themselves as they were sourced, scored, drafted, approved, replied to and booked, while the floor re-enacts it in lockstep. Read-only: nothing here sends or mutates anything."
109	      />
110	      <HydrationGate hydrated={hydrated} fallback={<SkeletonCard className="h-96" />}>
111	        {stream.length === 0 ? (
112	          <EmptyState
113	            icon={<Rewind className="h-7 w-7" aria-hidden />}
114	            title="Nothing to replay yet"
115	            description="The replay reconstructs itself from real candidate, outreach, reply and booking history. Source and work a campaign first."
116	            action={
117	              <Link
118	                href="/campaigns"
119	                className="inline-flex h-11 items-center rounded-full bg-tangerine px-6 text-sm font-semibold text-white shadow-soft hover:bg-tangerine/90"
120	              >
121	                Go to Campaigns
122	              </Link>
123	            }
124	          />
125	        ) : (
126	          <div className="grid grid-cols-1 gap-6 lg:grid-cols-[minmax(0,1fr)_360px]">
127	            <div className="flex flex-col gap-6">
128	              <div className="rounded-2xl border border-line bg-surface/60 p-4">
129	                <RunTimeline
130	                  events={stream}
131	                  minMs={minMs}
132	                  maxMs={maxMs}
133	                  cursorMs={effectiveCursor}
134	                  onScrub={setCursorMs}
135	                  soundEnabled={settings.soundEnabled}
136	                />
137	                <p className="mt-3 text-xs text-muted">
138	                  {formatDateTime(new Date(effectiveCursor).toISOString())} ·{" "}
139	                  {derived.events.length} of {stream.length} events revealed
140	                </p>
141	              </div>
142	              {/* `agents` is required by Floor3DProps but never actually shown here —
143	                  /replay always drives the scene through the additive `agentsOverride`
144	                  prop (src/components/floor3d/Floor3D.tsx) with the derived history
145	                  reconstruction, never the live fleet. */}
146	              <Floor3D
147	                agents={[]}
148	                agentsOverride={derived.agents}
149	                selectedId={selectedAgentId}
150	                onSelect={setSelectedAgentId}
151	              />
152	            </div>
153	            <div className="flex flex-col gap-3">
154	              <Eyebrow>Revealed candidates ({revealedCandidates.length})</Eyebrow>
155	              {revealedCandidates.length === 0 ? (
156	                <EmptyState
157	                  icon={<Users className="h-6 w-6" aria-hidden />}
158	                  title="Nothing revealed yet"
159	                  description="Drag the playhead forward to reveal candidates."
160	                />
161	              ) : (
162	                <div className="flex max-h-[70vh] flex-col gap-2 overflow-y-auto pr-1">
163	                  {revealedCandidates.map((raw) => {
164	                    const c = applyConfidentiality(raw, {
165	                      confidentialityMode: settings.confidentialityMode,
166	                      reveal: hasOutreachPurpose(raw.stage),
167	                    });
168	                    const lastEvent = lastEventByCandidate.get(raw.id);
169	                    return (
170	                      <div
171	                        key={c.id}
172	                        className="rounded-2xl border border-line bg-surface/60 p-3 animate-fade-in"
173	                      >
174	                        <div className="flex items-start gap-3">
175	                          <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-ink/5 text-xs font-bold text-ink-soft">
176	                            {c.avatarInitials || initialsFrom(c.name)}
177	                          </div>
178	                          <div className="min-w-0 flex-1">
179	                            <div className="flex items-center justify-between gap-2">
180	                              <p className="truncate text-sm font-semibold text-ink">{c.name}</p>
181	                              <Badge tone={toneForStage(c.stage)} size="sm" dot>
182	                                {c.stage}
183	                              </Badge>
184	                            </div>
185	                            <p className="truncate text-xs text-muted">
186	                              {c.currentTitle} · {c.currentCompany}
187	                            </p>
188	                            {lastEvent && (
189	                              <p className="mt-1 truncate text-xs text-ink-soft">
190	                                {KIND_LABEL[lastEvent.kind]}: {lastEvent.label}
191	                              </p>
192	                            )}
193	                          </div>
194	                        </div>
195	                      </div>
196	                    );
197	                  })}
198	                </div>
199	              )}
200	            </div>
201	          </div>
202	        )}
203	      </HydrationGate>
204	    </div>
205	  );
206	}

  1	import { NextResponse, type NextRequest } from "next/server";
  2	import { createServerClient, type CookieOptions } from "@supabase/ssr";
  3	import { SUPABASE_ANON_KEY, SUPABASE_AUTH_COOKIE_NAME, SUPABASE_URL, supabaseEnabled, ALLOWED_EMAIL_DOMAIN, isProduction, demoLoginEnabled, DEMO_COOKIE_NAME } from "@/lib/supabase/config";
  4	import { verifyDemoTokenAtEdge } from "@/lib/demo-auth-edge";
  5	
  6	type CookieToSet = { name: string; value: string; options?: CookieOptions };
  7	
  8	/** Routes that must stay reachable without a session: the auth screens and the
  9	 *  public career-site chatbox (external candidates never log in). */
 10	function isPublicPath(path: string): boolean {
 11	  return (
 12	    path.startsWith("/login") ||
 13	    path.startsWith("/auth") ||
 14	    path.startsWith("/careers") ||
 15	    path.startsWith("/unsubscribe")
 16	  );
 17	}
 18	
 19	/** API handlers that authenticate with a provider signature/bearer or are
 20	 * deliberately public. They must remain reachable without a demo session. */
 21	function isPublicServiceApi(path: string): boolean {
 22	  return (
 23	    path === "/api/health" ||
 24	    path === "/api/auth/demo-login" ||
 25	    path.startsWith("/api/careers") ||
 26	    path.startsWith("/api/unsubscribe/") ||
 27	    path.startsWith("/api/webhooks/") ||
 28	    path.startsWith("/api/cron/")
 29	  );
 30	}
 31	
 32	/**
 33	 * Route gate. In non-production DEMO mode (no Supabase env) it is a no-op — the
 34	 * app is open for local development. In production with no Supabase env it FAILS
 35	 * CLOSED (503) rather than granting open access. In LIVE mode it refreshes the
 36	 * Supabase session and redirects unauthenticated users to /login (Microsoft SSO).
 37	 * /login and /auth/* stay public.
 38	 */
 39	export async function proxy(req: NextRequest) {
 40	  const requestPath = req.nextUrl.pathname;
 41	  const apiRequest = requestPath === "/api" || requestPath.startsWith("/api/");
 42	  if (!supabaseEnabled) {
 43	    const validDemoSession = demoLoginEnabled
 44	      ? await verifyDemoTokenAtEdge(req.cookies.get(DEMO_COOKIE_NAME)?.value, process.env.DEMO_SESSION_SECRET)
 45	      : false;
 46	    // Preserve each API handler's own JSON auth, provider-signature, cron-secret,
 47	    // public, or liveness contract. This is the same ownership boundary APIs had
 48	    // before they were added to the matcher for live-session domain enforcement.
 49	    if (apiRequest) {
 50	      if (!demoLoginEnabled || isPublicServiceApi(requestPath)) return NextResponse.next();
 51	      if (!validDemoSession) {
 52	        return NextResponse.json(
 53	          { ok: false, reason: "Sign in to use this demo API." },
 54	          { status: 401 },
 55	        );
 56	      }
 57	      return NextResponse.next();
 58	    }
 59	    // Fail CLOSED in production. With no Supabase env the app would run in open
 60	    // DEMO mode (no login gate, every caller treated as admin) — never acceptable
 61	    // in prod. Refuse every matched route with a 503; only static assets are
 62	    // excluded from this gate.
 63	    //
 64	    // The ONE sanctioned exception is a deliberately public, synthetic-data demo
 65	    // (NEXT_PUBLIC_ENABLE_DEMO_LOGIN=true): there the open in-browser DEMO mode IS
 66	    // the intended product, so allow it through.
 67	    if (isProduction && !demoLoginEnabled) {
 68	      return new NextResponse(
 69	        "Service unavailable: server authentication is not configured.",
 70	        { status: 503, headers: { "content-type": "text/plain; charset=utf-8" } },
 71	      );
 72	    }
 73	    // Public demo: gate the app behind the one-click admin/admin login. The
 74	    // Web Crypto verifier works in the Edge runtime, so a forged cookie name is
 75	    // not enough to reach either pages or non-public APIs.
 76	    if (demoLoginEnabled) {
 77	      const path = requestPath;
 78	      const isAuthRoute = isPublicPath(path);
 79	      const hasSession = validDemoSession;
 80	      if (!hasSession && !isAuthRoute) {
 81	        const url = req.nextUrl.clone();
 82	        url.pathname = "/login";
 83	        url.searchParams.set("redirect", path);
 84	        return NextResponse.redirect(url);
 85	      }
 86	      if (hasSession && path.startsWith("/login")) {
 87	        const url = req.nextUrl.clone();
 88	        url.pathname = "/";
 89	        url.search = "";
 90	        return NextResponse.redirect(url);
 91	      }
 92	    }
 93	    // Non-production local dev, or a signed-in demo session: serve the app.
 94	    return NextResponse.next();
 95	  }
 96	
 97	  let res = NextResponse.next({ request: req });
 98	
 99	  const supabase = createServerClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
100	    cookieOptions: { name: SUPABASE_AUTH_COOKIE_NAME },
101	    cookies: {
102	      getAll() {
103	        return req.cookies.getAll();
104	      },
105	      setAll(cookiesToSet: CookieToSet[]) {
106	        cookiesToSet.forEach(({ name, value }) => req.cookies.set(name, value));
107	        res = NextResponse.next({ request: req });
108	        cookiesToSet.forEach(({ name, value, options }) => res.cookies.set(name, value, options));
109	      },
110	    },
111	  });
112	
113	  const {
114	    data: { user },
115	  } = await supabase.auth.getUser();
116	
117	  const path = requestPath;
118	  const isAuthRoute = isPublicPath(path);
119	  const isApiRoute = apiRequest;
120	
121	  // API handlers keep their own JSON authentication or signature contract.
122	  // The shared gate applies organization membership whenever a session exists,
123	  // but does not redirect anonymous API clients to an HTML login page.
124	  if (!user && !isAuthRoute && !isApiRoute) {
125	    const url = req.nextUrl.clone();
126	    url.pathname = "/login";
127	    url.searchParams.set("redirect", path);
128	    return NextResponse.redirect(url);
129	  }
130	
131	  // Enforce the email-domain allow-list when configured (display alone is not a gate).
132	  if (user && ALLOWED_EMAIL_DOMAIN && !isAuthRoute) {
133	    const email = (user.email ?? "").toLowerCase();
134	    if (!email.endsWith(`@${ALLOWED_EMAIL_DOMAIN.toLowerCase()}`)) {
135	      if (isApiRoute) {
136	        return NextResponse.json(
137	          { ok: false, reason: "Email domain is not authorized." },
138	          { status: 403 },
139	        );
140	      }
141	      const url = req.nextUrl.clone();
142	      url.pathname = "/auth/signout";
143	      url.search = "";
144	      return NextResponse.redirect(url);
145	    }
146	  }
147	
148	  if (user && path.startsWith("/login")) {
149	    const url = req.nextUrl.clone();
150	    url.pathname = "/";
151	    return NextResponse.redirect(url);
152	  }
153	
154	  return res;
155	}
156	
157	export const config = {
158	  // API routes are included so an authenticated off-domain session cannot
159	  // bypass the organization gate. Static assets and image files stay excluded.
160	  matcher: [
161	    "/api/:path*",
162	    "/((?!_next/static|_next/image|favicon.ico|icon.svg|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)",
163	  ],
164	};

