659	export const WIN_RECORD_LIMIT = 500;
660	
661	export function deriveWinRecord(
662	  state: HermesState,
663	  candidate: Candidate,
664	  campaign: Campaign,
665	  booking: Booking,
666	): WinRecord {
667	  try {
668	    const outreachById = new Map(state.outreach.map((message) => [message.id, message]));
669	    const joined = candidate.outreachHistory
670	      .map((entry) => {
671	        const message = outreachById.get(entry.messageId);
672	        return message ? { entry, message } : null;
673	      })
674	      .filter((item): item is NonNullable<typeof item> => item !== null);
675	    const realSends = joined
676	      .filter(({ message }) => isRealSendFact(message))
677	      .sort((a, b) => {
678	        const aAt = new Date(a.message.sentAt ?? a.entry.at).getTime();
679	        const bAt = new Date(b.message.sentAt ?? b.entry.at).getTime();
680	        return aAt - bAt;
681	      });
682	    const earliestRealSend = realSends[0] ?? null;
683	    const winningSend = realSends[realSends.length - 1] ?? null;
684	    const newestReply =
685	      state.replies
686	        .filter((reply) => reply.candidateId === candidate.id)
687	        .sort((a, b) => new Date(b.receivedAt).getTime() - new Date(a.receivedAt).getTime())[0] ?? null;
688	    const bookingAt = new Date(booking.createdAt).getTime();
689	    const firstSendAt = earliestRealSend
690	      ? new Date(earliestRealSend.message.sentAt ?? earliestRealSend.entry.at).getTime()
691	      : Number.NaN;
692	
693	    return {
694	      id: genId("win"),
695	      at: booking.createdAt,
696	      candidateId: candidate.id,
697	      candidateName: candidate.name,
698	      campaignId: campaign.id,
699	      campaignTitle: campaign.title,
700	      bookingId: booking.id,
701	      sourcePlatform: candidate.sourcePlatform,
702	      leadSource: candidate.leadSource ?? deriveLeadSource(candidate),
703	      matchScore: candidate.matchScore,
704	      seniority: campaign.jobAnalysis.seniority,
705	      roleTitle: campaign.jobAnalysis.title,
706	      outreachChannel: winningSend?.message.channel ?? null,
707	      touchCount: realSends.length,
708	      timeToBookMs:
709	        Number.isFinite(bookingAt) && Number.isFinite(firstSendAt)
710	          ? Math.max(0, bookingAt - firstSendAt)
711	          : null,
712	      triggeringReplyIntent: newestReply
713	        ? { intent: newestReply.intent, confidence: newestReply.confidence }
714	        : null,
715	      messageTraits: winningSend
716	        ? {
717	            subjectLength: winningSend.message.subject.length,
718	            bodyLength: winningSend.message.body.length,
719	            tone: winningSend.message.tone,
720	          }
721	        : {},
722	    };
723	  } catch {
724	    return {
725	      id: genId("win"),
726	      at: booking.createdAt,
727	      candidateId: candidate.id,
728	      candidateName: candidate.name,
729	      campaignId: campaign.id,
730	      campaignTitle: campaign.title,
731	      bookingId: booking.id,
732	      sourcePlatform: candidate.sourcePlatform,
733	      leadSource: candidate.leadSource ?? null,
734	      matchScore: candidate.matchScore,
735	      seniority: campaign.jobAnalysis.seniority,
736	      roleTitle: campaign.jobAnalysis.title,
737	      outreachChannel: candidate.outreachHistory[0]?.channel ?? null,
738	      touchCount: 0,
739	      timeToBookMs: null,
740	      triggeringReplyIntent: candidate.replyHistory[0]
741	        ? {
742	            intent: candidate.replyHistory[0].intent,
743	            confidence: candidate.replyHistory[0].confidence,
744	          }
745	        : null,
746	      messageTraits: {},
747	    };
748	  }
749	}
750	
751	export function appendWinRecord(
752	  state: HermesState,
753	  candidate: Candidate,
754	  campaign: Campaign,
755	  booking: Booking,
756	): HermesState {
757	  const win = deriveWinRecord(state, candidate, campaign, booking);
758	  return { ...state, wins: [win, ...(state.wins ?? [])].slice(0, WIN_RECORD_LIMIT) };
759	}
