   288	
   289	export function globalKpis(
   290	  state: Pick<
   291	    HermesState,
   292	    "campaigns" | "candidates" | "outreach" | "replies" | "bookings" | "settings"
   293	  >,
   294	): GlobalKpis {
   295	  const active = state.campaigns.filter((c) => !["Filled", "Paused"].includes(c.status));
   296	  const facts = realFunnelFacts(state, { live: !state.settings.dryRunMode });
   297	  const candidateIds = new Set(facts.candidateIds);
   298	  const cands = state.candidates.filter((c) => candidateIds.has(c.id));
   299	  const interested = cands.filter(
   300	    (c) => effectiveStageRank(c) >= 3 && c.stage !== "Not Interested",
   301	  ).length;
   302	  const awaitingBooking = cands.filter((c) => c.stage === "Interested" && !c.booking).length;
   303	  const scores = cands.map((c) => c.matchScore).filter(Boolean);
   304	  const avg = scores.length ? round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
   305	  // Mean time-to-first-interview across ACTIVE campaigns only.
   306	  const ttfi = active
   307	    .map((c) => c.metrics.timeToFirstInterviewHours)
   308	    .filter((v): v is number => v != null);
   309	
   310	  return {
   311	    activeCampaigns: active.length,
   312	    totalCampaigns: state.campaigns.length,
   313	    candidatesSourced: facts.sourced,
   314	    contacted: facts.contacted,
   315	    replyRate: facts.replyRate,
   316	    interviewsBooked: facts.booked,
   317	    interested,
   318	    awaitingBooking,
   319	    avgMatchScore: avg,
   320	    timeToFirstInterviewHours: ttfi.length ? round(ttfi.reduce((a, b) => a + b, 0) / ttfi.length) : null,
   321	    pendingApprovals: state.outreach.filter(
   322	      (m) =>
   323	        candidateIds.has(m.candidateId) &&
   324	        (m.status === "Needs Approval" || m.status === "Pending Manual Send"),
   325	    ).length,
   326	    hotReplies: state.replies.filter(
   327	      (r) =>
   328	        candidateIds.has(r.candidateId) &&
   329	        !r.handled &&
   330	        ["INTERESTED", "QUALIFIED_INTEREST"].includes(r.intent),
   331	    ).length,
   332	  };
   333	}
